protected calculateCost(tokensUsed: { prompt: number; completion: number }): number {
  // Claude Opus pricing (adjust as needed)
  const promptCost = (tokensUsed.prompt / 1000) * 0.015;
  const completionCost = (tokensUsed.completion / 1000) * 0.075;
  return promptCost + completionCost;
}

private convertMessages(messages: Message[], systemPrompt?: string): {

    const completionCost = (tokensUsed.completion / 1000) * 0.075;
    return promptCost + completionCost;
  }

  private convertMessages(messages: Message[], systemPrompt?: string): OpenAI.ChatCompletionMessageParam[] {
    const result: OpenAI.ChatCompletionMessageParam[] = [];

    if (systemPrompt) {
      result.push({ role: 'system', content: systemPrompt });
    }

    for (const msg of messages) {
      if (msg.role === 'system' || msg.role === 'user' || msg.role === 'assistant') {
        result.push({ role: msg.role, content: msg.content });
      }
    }

    return result;
  }
